import XCTest
final class APIProtocolUITests:XCTestCase {
    override func setUp(){super.setUp();continueAfterFailure=false}
    private func launch(_ extra:[String]=[])->XCUIApplication{let app=XCUIApplication();app.launchArguments=["--native-api-testing","--native-api-protocol-testing"]+extra;app.launch();XCTAssertTrue(app.buttons["protocol-review"].waitForExistence(timeout:15));return app}
    private func reveal(_ element:XCUIElement,_ app:XCUIApplication){for _ in 0..<30{let top=app.navigationBars.firstMatch.frame.maxY+4,bottom=app.buttons["protocol-review"].exists ? app.buttons["protocol-review"].frame.minY-8 : app.frame.maxY-70;if element.exists && element.isHittable && element.frame.midY>top && element.frame.midY<bottom{return};let delta:CGFloat=element.exists && element.frame.midY<top ? 120 : -140;let start=app.coordinate(withNormalizedOffset:CGVector(dx:0.85,dy:0.5));start.press(forDuration:0.1,thenDragTo:start.withOffset(CGVector(dx:0,dy:delta)),withVelocity:.slow,thenHoldForDuration:0.1)};capture("protocol-control-not-found",app);let debug=XCTAttachment(string:app.debugDescription);debug.lifetime = .keepAlways;add(debug);XCTAssertTrue(element.exists);XCTAssertTrue(element.isHittable)}
    private func capture(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
    func testNativeSectionsAndActivityReadiness(){let app=launch();let activity=app.buttons["protocol-activity-activity-0"];reveal(activity,app);activity.tap();XCTAssertEqual(app.webViews.count,0);capture("protocol-light-activities",app);app.buttons["protocol-review"].tap();XCTAssertTrue(app.navigationBars["Zkontrolovat protokol"].waitForExistence(timeout:10));XCTAssertTrue(app.buttons["protocol-finalize"].isEnabled);capture("protocol-review",app)}
    func testCatalogSearchDecimalQuantitiesAndSeveralItems(){let app=launch();let section=app.descendants(matching:.any)["protocol-section-materialItems"].firstMatch;reveal(section,app);section.tap();let open=app.buttons["protocol-catalog"];reveal(open,app);open.tap();let search=app.searchFields.firstMatch;XCTAssertTrue(search.waitForExistence(timeout:10));search.tap();search.typeText("Rotační");let quantity=app.textFields["protocol-quantity-material-1"];XCTAssertTrue(quantity.waitForExistence(timeout:10));quantity.tap();quantity.typeText(XCUIKeyboardKey.delete.rawValue+"1,5");app.buttons["protocol-quantity-done"].tap();search.tap();search.buttons["Smazat text"].tap();let meters=app.textFields["protocol-quantity-material-2"];XCTAssertTrue(meters.waitForExistence(timeout:10));meters.tap();meters.typeText(XCUIKeyboardKey.delete.rawValue+"2,25");app.buttons["protocol-quantity-done"].tap();capture("protocol-material-catalog",app);app.buttons["protocol-catalog-done"].tap();XCTAssertTrue(app.buttons["protocol-review"].waitForExistence(timeout:10));XCTAssertTrue(app.staticTexts["2 položek"].exists)}
    func testSignatureNeedsActualInkThenConfirms(){let app=launch(["--protocol-filled"]);let section=app.descendants(matching:.any)["protocol-section-signature"].firstMatch;reveal(section,app);section.tap();let open=app.buttons["protocol-signature"];reveal(open,app);open.tap();XCTAssertTrue(app.navigationBars["Podpis zákazníka"].waitForExistence(timeout:10));let confirm=app.buttons["protocol-signature-confirm"];XCTAssertFalse(confirm.isEnabled);let canvas=app.otherElements["protocol-signature-canvas"];XCTAssertTrue(canvas.waitForExistence(timeout:10));let a=canvas.coordinate(withNormalizedOffset:CGVector(dx:0.15,dy:0.4)),b=canvas.coordinate(withNormalizedOffset:CGVector(dx:0.8,dy:0.65));a.press(forDuration:0.1,thenDragTo:b);expectation(for:NSPredicate(format:"enabled == true"),evaluatedWith:confirm);waitForExpectations(timeout:10);capture("protocol-customer-signature",app);confirm.tap();XCTAssertTrue(app.buttons["protocol-review"].waitForExistence(timeout:10))}
    func testConfirmedDarkAppearanceAndPDF(){let app=launch(["--protocol-confirmed","--native-ui-dark-testing"]);XCTAssertTrue(app.staticTexts["Potvrzeno"].exists);capture("protocol-confirmed-dark",app);app.buttons["protocol-pdf"].tap();let pdf=app.otherElements["QLPDFViewControllerViewAccessibilityIdentifier"];XCTAssertTrue(pdf.waitForExistence(timeout:15));XCTAssertEqual(app.webViews.count,0);capture("protocol-pdf-native",app)}
    func testManagerCanOpenAndDeactivateTemplate(){let app=launch();app.buttons["Možnosti protokolu"].tap();app.buttons["Správa šablon a činností"].tap();XCTAssertTrue(app.navigationBars["Šablony protokolů"].waitForExistence(timeout:10));app.buttons["protocol-template-service"].tap();XCTAssertTrue(app.navigationBars["Upravit šablonu"].waitForExistence(timeout:10));let active=app.switches["Aktivní"];XCTAssertTrue(active.waitForExistence(timeout:10));active.coordinate(withNormalizedOffset:CGVector(dx:0.9,dy:0.5)).tap();XCTAssertEqual(active.value as? String,"0");app.navigationBars.buttons["Uložit"].tap();let row=app.buttons["protocol-template-service"];expectation(for:NSPredicate(format:"label CONTAINS %@","Deaktivovaná · 6 činností"),evaluatedWith:row);waitForExpectations(timeout:10);capture("protocol-template-management",app)}
    func testLargeTextKeepsMainActionsWithinScreen(){let app=launch(["--protocol-large-text"]);let action=app.buttons["protocol-review"];XCTAssertTrue(action.isHittable);XCTAssertLessThanOrEqual(action.frame.maxX,app.frame.maxX);XCTAssertGreaterThanOrEqual(action.frame.minX,app.frame.minX);XCTAssertEqual(app.webViews.count,0);capture("protocol-large-text",app)}
}
